insert into public.rights_holders (id, name, category, eras, profile, representative_seed, confidence, notes, batch) values
  ('televisa', 'TelevisaUnivision', 'novela_latina', array['now']::text[], '{"estilo":"relacional","prioridades":["exclusividade","exposicao_tv_aberta","parceria_longa"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Rodrigo Salinas","cargo":"Vice-presidente de vendas para a América Latina","estilo":"cordial, fala de \"família Televisa\" e de parceria histórica","ficticio":true}'::jsonb, 'alta', 'Web: exclusividade de novelas na TV aberta com o SBT, estendida por cinco anos em 2023 (Meio & Mensagem, https://www.meioemensagem.com.br/midia/sbt-e-televisaunivision-estendem-acordo-por-mais-cinco-anos). Representante fictício.', '2026-lote1'),
  ('grupo_chespirito', 'Grupo Chespirito', 'novela_latina', array['now']::text[], '{"estilo":"duro","prioridades":["preco","respeito_a_obra"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Martina Ochoa","cargo":"Diretora de licenciamento","estilo":"protetora da obra, desconfia de cortes e reprises demais","ficticio":true}'::jsonb, 'media', 'Memória: dono dos direitos das séries de Chespirito (Chaves, Chapolin); houve disputa com a Televisa que tirou Chaves do ar no Brasil por alguns anos. Conferir a situação dos direitos em 2026.', '2026-lote1'),
  ('rcn', 'RCN Televisión', 'novela_latina', array['now']::text[], '{"estilo":"relacional","prioridades":["preco","exposicao_tv_aberta"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Catalina Restrepo","cargo":"Gerente de vendas internacionais","estilo":"calorosa e direta, gosta de citar sucessos colombianos","ficticio":true}'::jsonb, 'alta', 'Memória: emissora e produtora colombiana (Betty, a Feia; Café com Aroma de Mulher).', '2026-lote1'),
  ('caracol', 'Caracol Televisión', 'novela_latina', array['now']::text[], '{"estilo":"leiloeiro","prioridades":["preco","multiplataforma"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Andrés Mejía","cargo":"Diretor de distribuição internacional","estilo":"negociador frio, compara ofertas de streaming","ficticio":true}'::jsonb, 'alta', 'Memória: emissora e produtora colombiana (O Patrão do Mal).', '2026-lote1'),
  ('telemundo', 'Telemundo Global Studios (NBCUniversal)', 'novela_latina', array['now']::text[], '{"estilo":"leiloeiro","prioridades":["preco","multiplataforma"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Valeria Montes","cargo":"Executiva de vendas para o Brasil","estilo":"objetiva, fala em pacotes e janelas","ficticio":true}'::jsonb, 'alta', 'Memória: estúdio de novelas e séries em espanhol do grupo NBCUniversal (A Rainha do Sul).', '2026-lote1'),
  ('global_agency', 'Global Agency', 'novela_turca', array['now']::text[], '{"estilo":"leiloeiro","prioridades":["preco","exposicao_tv_aberta"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Selin Arslan","cargo":"Diretora de vendas para as Américas","estilo":"enérgica, cria senso de urgência com outras emissoras","ficticio":true}'::jsonb, 'alta', 'Memória: distribuidora turca de dramas para o mundo. Quais títulos ela distribui está indicado em cada título.', '2026-lote1'),
  ('inter_medya', 'Inter Medya', 'novela_turca', array['now']::text[], '{"estilo":"relacional","prioridades":["relacionamento","preco"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Kerem Yıldız","cargo":"Vice-presidente de vendas","estilo":"paciente, aposta em parcerias de vários títulos","ficticio":true}'::jsonb, 'alta', 'Web: distribuidora turca com Terra Amarga (Bitter Lands) e Deception no catálogo (https://todotvnews.com/en/inter-medya-strikes-new-international-deals-for-its-turkish-dramas/, https://tvbizzmagazine.com/the-turkish-distributors-bring-their-biggest-hits).', '2026-lote1'),
  ('madd', 'MADD Entertainment', 'novela_turca', array['now']::text[], '{"estilo":"relacional","prioridades":["preco","exposicao_tv_aberta"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Deniz Kaya","cargo":"Gerente de vendas para a América Latina","estilo":"simpático, fala muito de audiência na Turquia","ficticio":true}'::jsonb, 'alta', 'Web: distribuidora turca com vendas internacionais recentes (https://broadcastprome.com/news/ottvideo-streaming/madd-entertainment-secures-multiple-sales-for-turkish-series-across-cee-cis-and-africa). Os títulos ligados a ela estão com confiança baixa: conferir.', '2026-lote1'),
  ('kanal_d', 'Kanal D International', 'novela_turca', array['now']::text[], '{"estilo":"leiloeiro","prioridades":["preco"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Emre Demir","cargo":"Diretor de vendas internacionais","estilo":"pragmático, quer fechar rápido","ficticio":true}'::jsonb, 'media', 'Memória: braço internacional do canal turco Kanal D. Conferir quais títulos do lote ele distribui.', '2026-lote1'),
  ('eccho_rights', 'Eccho Rights', 'novela_turca', array['now']::text[], '{"estilo":"relacional","prioridades":["preco","relacionamento"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Ayla Şahin","cargo":"Gerente de contas para as Américas","estilo":"detalhista, discute cada cláusula","ficticio":true}'::jsonb, 'media', 'Memória: distribuidora com forte catálogo turco. Conferir títulos.', '2026-lote1'),
  ('cj_enm', 'CJ ENM', 'asiatico', array['now']::text[], '{"estilo":"duro","prioridades":["preco","multiplataforma"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Min-ji Park","cargo":"Diretora de vendas internacionais","estilo":"formal, preocupada com dublagem e janelas de streaming","ficticio":true}'::jsonb, 'alta', 'Memória: grupo sul-coreano dono do canal tvN e do Studio Dragon (doramas).', '2026-lote1'),
  ('wbd', 'Warner Bros. Discovery', 'estudio_eua', array['now']::text[], '{"estilo":"duro","prioridades":["preco","pacote","multiplataforma"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Laura Bennett","cargo":"Vice-presidente de vendas de conteúdo para o Brasil","estilo":"firme, vende em pacote e cobra por exibição","ficticio":true}'::jsonb, 'alta', 'Memória: estúdio de cinema e TV (Friends, The Big Bang Theory, Harry Potter). Também detém direitos esportivos (Champions League 2027–2031, seção 8B).', '2026-lote1'),
  ('disney', 'The Walt Disney Company', 'estudio_eua', array['now']::text[], '{"estilo":"duro","prioridades":["preco","protecao_de_marca","multiplataforma"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Mark Holloway","cargo":"Diretor de distribuição para a TV aberta","estilo":"educado e inflexível com horário e classificação","ficticio":true}'::jsonb, 'alta', 'Memória: estúdios Disney, Pixar e ABC Signature (Lost, Grey’s Anatomy). Prioriza o próprio streaming.', '2026-lote1'),
  ('nbcu', 'NBCUniversal', 'estudio_eua', array['now']::text[], '{"estilo":"leiloeiro","prioridades":["preco","pacote"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Jenna Marlowe","cargo":"Executiva de vendas internacionais","estilo":"rápida, gosta de pacotes grandes","ficticio":true}'::jsonb, 'alta', 'Memória: Universal Pictures e Universal Television (The Office, Lei & Ordem: SVU).', '2026-lote1'),
  ('sony', 'Sony Pictures Television', 'estudio_eua', array['now']::text[], '{"estilo":"relacional","prioridades":["preco","pacote"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Daniel Cortez","cargo":"Vice-presidente para a América Latina","estilo":"cordial, oferece formatos junto com séries","ficticio":true}'::jsonb, 'alta', 'Memória: séries (Breaking Bad, The Good Doctor) e formatos (Shark Tank).', '2026-lote1'),
  ('paramount', 'Paramount', 'estudio_eua', array['now']::text[], '{"estilo":"leiloeiro","prioridades":["preco","pacote"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Rachel Stone","cargo":"Diretora de licenciamento internacional","estilo":"objetiva, negocia por temporada","ficticio":true}'::jsonb, 'media', 'Memória: Paramount Pictures e CBS Studios (CSI). A empresa passou por fusão em 2025; conferir o nome usado em 2026.', '2026-lote1'),
  ('banijay', 'Banijay', 'formato', array['now']::text[], '{"estilo":"relacional","prioridades":["relacionamento","preco","exclusividade"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Sophie Marchand","cargo":"Diretora de formatos para a América Latina","estilo":"protetora do formato, exige seguir a \"bíblia\"","ficticio":true}'::jsonb, 'alta', 'Memória: dona da Endemol Shine (Big Brother, MasterChef, Survivor, Deal or No Deal).', '2026-lote1'),
  ('itv_studios', 'ITV Studios', 'formato', array['now']::text[], '{"estilo":"relacional","prioridades":["preco","exposicao_tv_aberta"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Oliver Grant","cargo":"Vice-presidente de formatos","estilo":"entusiasmado, fala em \"temporada de estreia\"","ficticio":true}'::jsonb, 'alta', 'Memória: dona da Talpa (The Voice) e de Hell’s Kitchen.', '2026-lote1'),
  ('fremantle', 'Fremantle', 'formato', array['now']::text[], '{"estilo":"relacional","prioridades":["preco","exposicao_tv_aberta"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Isabella Romano","cargo":"Diretora de vendas de formatos","estilo":"animada, cita sucessos em vários países","ficticio":true}'::jsonb, 'alta', 'Memória: Got Talent, Idols, The Price Is Right.', '2026-lote1'),
  ('bbc_studios', 'BBC Studios', 'formato', array['now']::text[], '{"estilo":"duro","prioridades":["preco","protecao_de_marca"],"calibrar_na_fase":"6.3"}'::jsonb, '{"nome":"Henry Ashford","cargo":"Diretor de formatos","estilo":"cerimonioso, exige padrão de produção","ficticio":true}'::jsonb, 'alta', 'Memória: Strictly Come Dancing / Dancing with the Stars.', '2026-lote1')
