  ('mil_e_uma_noites', 'Mil e Uma Noites', 'Binbir Gece', 'novela', 'Turquia', 'global_agency', 2006, 90, 90, '2026-01-05', null, '[{"emissora":"band","periodo":"2015"}]'::jsonb, '{"genre":"novela_21h","quality":72,"appeal":76,"fatigue":35,"estimativa":true}'::jsonb, 'media', 'Memória: a primeira novela turca de grande sucesso na TV aberta brasileira (Band). Duração dos capítulos varia conforme a edição; conferir distribuidora.', '2026-lote1'),
